    parent1_degree = applicant.parent1_degree
    parent2_degree = applicant.parent2_degree

    def get_degree_points(degree):
        if degree == 'non-degree':
            return 0
        elif degree == 'bachelor':
            return 1
        elif degree == 'master':
            return 2
        elif degree == 'PhD':
            return 3
        else:
            return 0

    parent1_points = get_degree_points(parent1_degree)
    parent2_points = get_degree_points(parent2_degree)
    total_parent_degrees = parent1_points + parent2_points
    score += total_parent_degrees

    # Evaluate personal statement
    if applicant.personal_statement == 'high quality':
        score += 2
    elif applicant.personal_statement == 'medium quality':
        score += 1

    return score

